node --input-type=module <<'EOF'
import { createPushGate } from './bot.mjs';
const out = [];
const check = (name, got, want) => { const ok = JSON.stringify(got) === JSON.stringify(want); out.push(`${ok ? 'PASS' : 'FAIL'} ${name}: ${JSON.stringify(got)}`); };
const tokyo = { id: 'u_8841', timeZone: 'Asia/Tokyo', quietStart: '22:00', quietEnd: '07:00', dailyCap: 3 };
const g = createPushGate();
check('first push allowed', g.attempt(tokyo, new Date('2026-10-23T03:00:00Z')), { allowed: true, reason: null }); // 12:00 JST
check('23:00 JST quiet', createPushGate().attempt(tokyo, new Date('2026-10-23T14:00:00Z')), { allowed: false, reason: 'quiet_hours' });
check('07:00 JST allowed (end exclusive)', createPushGate().attempt(tokyo, new Date('2026-10-23T22:00:00Z')), { allowed: true, reason: null });
check('21:59 JST allowed', createPushGate().attempt(tokyo, new Date('2026-10-23T12:59:00Z')), { allowed: true, reason: null });
const g2 = createPushGate();
const noon = new Date('2026-10-23T03:00:00Z');
check('cap 1', g2.attempt(tokyo, noon).allowed, true);
check('cap 2', g2.attempt(tokyo, noon).allowed, true);
check('cap 3', g2.attempt(tokyo, noon).allowed, true);
check('cap 4 blocked', g2.attempt(tokyo, noon), { allowed: false, reason: 'daily_cap_reached' });
check('new local day resets (00:30 JST next day)', g2.attempt(tokyo, new Date('2026-10-23T15:30:00Z')), { allowed: true, reason: null });
check('other user independent', g2.attempt({ ...tokyo, id: 'u_2' }, noon).allowed, true);
check('invalid zone held', createPushGate().attempt({ ...tokyo, timeZone: 'Mars/Base' }, noon), { allowed: false, reason: 'invalid_time_zone' });
check('bad quiet held', createPushGate().attempt({ ...tokyo, quietStart: '25:00' }, noon), { allowed: false, reason: 'invalid_quiet_hours' });
check('bad now held', createPushGate().attempt(tokyo, new Date('x')), { allowed: false, reason: 'invalid_now' });
check('cap 0 blocked', createPushGate().attempt({ ...tokyo, dailyCap: 0 }, noon), { allowed: false, reason: 'daily_cap_reached' });
const ny = { id: 'u_ny', timeZone: 'America/New_York', quietStart: '22:00', quietEnd: '07:00', dailyCap: 5 };
check('DST fall-back 06:30 EDT quiet', createPushGate().attempt(ny, new Date('2026-11-01T10:30:00Z')), { allowed: false, reason: 'quiet_hours' });
check('DST 07:00 EST allowed', createPushGate().attempt(ny, new Date('2026-11-01T12:00:00Z')), { allowed: true, reason: null });
check('same-day window no quiet', createPushGate().attempt({ ...tokyo, quietStart: '08:00', quietEnd: '08:00' }, new Date('2026-10-23T23:00:00Z')).allowed, true);
console.log(out.join('\n'));
console.log(out.some(l => l.startsWith('FAIL')) ? 'SELF-CHECK FAILED' : 'SELF-CHECK OK');
EOF

